+
+/**
+ * The same behaviour as {@link ContactViewTest}, checked in a real browser.
+ */
+@SpringBootTest(webEnvironment = SpringBootTest.WebEnvironment.RANDOM_PORT)
+class ContactViewBrowserTest extends AbstractBasePlaywrightIT {
+
+    @LocalServerPort
+    private int port;
+
+    @Override
+    public String getUrl() {
+        return "http://localhost:" + port;
+    }
+
+    @Override
+    public String getView() {
+        return "/contact";
+    }
+
+    private TextFieldElement name() {
+        return TextFieldElement.getByLabel(page, "Name");
+    }
+
+    private EmailFieldElement email() {
+        return EmailFieldElement.getByLabel(page, "Email");
+    }
+
+    private TextFieldElement phone() {
+        return TextFieldElement.getByLabel(page, "Phone");
+    }
+
+    private TextAreaElement message() {
+        return TextAreaElement.getByLabel(page, "Message");
+    }
+
+    private ButtonElement send() {
+        return ButtonElement.getByText(page, "Send");
+    }
+
+    private Locator aboutLink() {
+        return page.getByRole(AriaRole.LINK, new Page.GetByRoleOptions().setName("About"));
+    }
+
+    private void fillValidForm() {
+        name().setValue("Alice");
+        email().setValue("alice@example.com");
+        message().setValue("Hello there");
+    }
+
+    @Test
+    void formIsEmptyAndSendIsEnabled() {
+        assertThat(page.locator("h1")).hasText("Contact");
+        name().assertValue("");
+        email().assertValue("");
+        phone().assertValue("");
+        message().assertValue("");
+        send().assertEnabled();
+        assertThat(aboutLink()).isVisible();
+    }
+
+    @Test
+    void emptyFormIsRejectedWithMessages() {
+        send().click();
+
+        name().assertInvalid();
+        name().assertErrorMessage("Name is required");
+        email().assertInvalid();
+        email().assertErrorMessage("Give an e-mail address or a phone number");
+        message().assertInvalid();
+        message().assertErrorMessage("Message is required");
+
+        assertThat(page.locator("vaadin-notification-card")).hasCount(0);
+        assertEquals(0, GridElement.get(page).getTotalRowCount());
+    }
+
+    @Test
+    void malformedEmailIsRejected() {
+        name().setValue("Alice");
+        email().setValue("not-an-address");
+        message().setValue("Hello");
+        send().click();
+
+        email().assertInvalid();
+        email().assertErrorMessage("Enter a valid e-mail address");
+        name().assertValue("Alice");
+        assertEquals(0, GridElement.get(page).getTotalRowCount());
+    }
+
+    @Test
+    void tooLongMessageIsRejected() {
+        name().setValue("Alice");
+        phone().setValue("555-1234");
+        message().setValue("x".repeat(501));
+        send().click();
+
+        message().assertInvalid();
+        message().assertErrorMessage("Message must be at most 500 characters");
+        assertEquals(0, GridElement.get(page).getTotalRowCount());
+    }
+
+    @Test
+    void sendingShowsNotificationRowAndDisablesSendUntilNextEdit() {
+        fillValidForm();
+        send().click();
+
+        NotificationElement.getByText(page, "Message sent").assertOpen();
+
+        GridElement grid = GridElement.get(page);
+        assertThat(grid.getLocator()).containsText("Alice");
+        assertThat(grid.getLocator()).containsText("Hello there");
+
+        name().assertValue("");
+        email().assertValue("");
+        phone().assertValue("");
+        message().assertValue("");
+        send().assertDisabled();
+
+        name().setValue("B");
+        send().assertEnabled();
+    }
+
+    @Test
+    void enterSendsTheMessage() {
+        name().setValue("Alice");
+        phone().setValue("555-1234");
+        message().setValue("Sent with Enter");
+        message().getInputLocator().press("Enter");
+
+        NotificationElement.getByText(page, "Message sent").assertOpen();
+        assertThat(GridElement.get(page).getLocator()).containsText("Sent with Enter");
+    }
+
+    @Test
+    void aboutLinkNavigatesWithoutReloadingThePage() {
+        page.evaluate("window.__stillTheSamePage = true");
+        aboutLink().click();
+
+        assertThat(page.locator("h1")).hasText("About");
+        assertEquals(Boolean.TRUE, page.evaluate("window.__stillTheSamePage"));
+    }
+
+    @Test
+    void halfWrittenMessageIsProtectedWhenLeaving() {
+        message().setValue("half written");
+        aboutLink().click();
+
+        DialogElement dialog = new DialogElement(page);
+        dialog.assertOpen();
+
+        ButtonElement.getByText(page, "Keep editing").click();
+        dialog.assertClosed();
+        assertThat(page.locator("h1")).hasText("Contact");
+        message().assertValue("half written");
+
+        aboutLink().click();
+        new DialogElement(page).assertOpen();
+        ButtonElement.getByText(page, "Discard").click();
+        assertThat(page.locator("h1")).hasText("About");
+    }
+
+    @Test
+    void sentMessagesAreStillThereAfterVisitingAboutAndComingBack() {
+        fillValidForm();
+        send().click();
+        NotificationElement.getByText(page, "Message sent").assertOpen();
+
+        aboutLink().click();
+        assertThat(page.locator("h1")).hasText("About");
+        page.goBack();
+
+        assertThat(page.locator("h1")).hasText("Contact");
+        assertThat(GridElement.get(page).getLocator()).containsText("Alice");
+
+        page.reload();
+        assertThat(GridElement.get(page).getLocator()).containsText("Alice");
+    }
+}
